  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC2", "NAVC2", "R14"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47", "NAVC2.4"],
      "nets": ["NET0126", "NET0100", "NET0054", "NET0144", "NET0152"],
      "observed": "The STM32 VCAP pins are assigned to ordinary signal nets: FCC2.48 (VCAP) is on NET0126, which connects through R14 to NET0152/NAVC2.4 (PC15); FCC2.73 (VCAP) is on NET0100, used at the UART3_FCC2 connector. NAVC2.31 and .47 (VCAP_1 and VCAP_2) are on NET0054 and NET0144, which are also used by peripheral/connector signals.",
      "expected": "Each MCU VCAP pin should have its required local capacitor to GND and should not share a net with GPIO, UART, or other external signals. The STM32H753 and STM32F405 VCAP pins require dedicated capacitor connections.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC2: pin 48 VCAP NET0126; pin 73 VCAP NET0100 (Flight Control Computer, page 2/6)"
        },
        {
          "source": "schematic",
          "quote": "R14 10 between NET0126 and NET0152 (Connections, page 4/6)"
        },
        {
          "source": "schematic",
          "quote": "NAVC2: pin 31 VCAP_1 NET0054; pin 47 VCAP_2 NET0144 (Navigation Computer, page 3/6)"
        },
        {
          "source": "schematic",
          "quote": "UART3_FCC2 connector signal NET0100; I2C3_NAVC2 connector signal NET0054 (FCC Peripherals and NAVC Peripherals, pages 5/6 and 6/6)"
        },
        {
          "source": "spec",
          "quote": "FCC is populated with an STM32H753VITx and the NAVC with an STM32F405RGTx"
        }
      ],
      "impact": "The VCAP pins are part of the MCUs' internal regulator supply and must not be driven by external signals. These connections can prevent reliable MCU operation and may cause signal contention or damage; the missing dedicated VCAP capacitors further compromise operation.",
      "confidence": 0.99
    },
    {
      "category": "missing_component",
      "components": ["FCC2", "NAVC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0126", "NET0100", "NET0054", "NET0144"],
      "observed": "No dedicated capacitors from the four MCU VCAP pins to GND are shown on the FCC or NAVC sheets.",
      "expected": "Provide the MCU-required VCAP capacitors to GND, one for each VCAP pin, in accordance with the STM32H753 and STM32F405 datasheets.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC2 VCAP pins 48 and 73 are labeled NET0126 and NET0100; the shown decoupling capacitors are on +3V3 (Flight Control Computer, page 2/6)"
        },
        {
          "source": "schematic",
          "quote": "NAVC2 VCAP_1 pin 31 and VCAP_2 pin 47 are labeled NET0054 and NET0144; no VCAP capacitors are shown (Navigation Computer, page 3/6)"
        }
      ],
      "impact": "Without the required VCAP capacitors, the MCUs' internal regulators may not function correctly, preventing reliable startup or operation.",
      "confidence": 0.98
    }
  ],
  "summary": "The schematic connects MCU VCAP pins to unrelated signal nets and shows no dedicated VCAP capacitors. This violates the STM32 power requirements and is likely to make the control computers unreliable or nonfunctional."
}

